    37  // Test that the ZMTP engine handles invalid handshake when connecting
    38  // https://rfc.zeromq.org/spec/37/
    39  extern "C" int LLVMFuzzerTestOneInput (const uint8_t *data, size_t size)
    40  {
    41      setup_test_context ();
    42      char my_endpoint[MAX_SOCKET_STRING];
    43      fd_t server = bind_socket_resolve_port ("127.0.0.1", "0", my_endpoint);
    44
    45      void *client = test_context_socket (ZMQ_PUB);
    46      TEST_ASSERT_SUCCESS_ERRNO (zmq_connect (client, my_endpoint));
    47
    48      fd_t server_accept =
    49        TEST_ASSERT_SUCCESS_RAW_ERRNO (accept (server, NULL, NULL));
    50      for (ssize_t sent = 0; size > 0 && (sent != -1 || errno == EINTR);
    51           size -= sent > 0 ? sent : 0, data += sent > 0 ? sent : 0)
    52          sent = send (server_accept, (const char *) data, size, MSG_NOSIGNAL);
    53      msleep (250);
    54
    55      close (server_accept);
    56      close (server);
    57
    58      test_context_socket_close_zero_linger (client);
    59      teardown_test_context ();
    60
    61      return 0;
    62  }
